CREATE TYPE "ForceCurveMappingState" AS ENUM ('AUTO_APPROVED','REVIEW_REQUIRED','MANUALLY_APPROVED','REJECTED','NO_MATCH','STALE');
CREATE TYPE "ForceCurveReviewStatus" AS ENUM ('OPEN','RESOLVED');
CREATE TYPE "ForceCurveSyncStatus" AS ENUM ('RUNNING','COMPLETED','FAILED');
CREATE TABLE "ForceCurveCatalogEntry" ("id" TEXT PRIMARY KEY, "source" TEXT NOT NULL, "repositoryPath" TEXT NOT NULL, "displayName" TEXT NOT NULL, "manufacturer" TEXT, "technology" "SwitchTechnology", "revision" TEXT, "contentHash" TEXT, "exists" BOOLEAN NOT NULL DEFAULT true, "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "ForceCurveCatalogEntry_source_repositoryPath_key" ON "ForceCurveCatalogEntry"("source","repositoryPath");
CREATE INDEX "ForceCurveCatalogEntry_exists_idx" ON "ForceCurveCatalogEntry"("exists");
CREATE TABLE "ForceCurveMapping" ("id" TEXT PRIMARY KEY, "masterSwitchId" TEXT NOT NULL, "catalogEntryId" TEXT, "state" "ForceCurveMappingState" NOT NULL, "confidence" DOUBLE PRECISION, "provenance" TEXT NOT NULL, "reason" TEXT, "decidedById" TEXT, "noMatchKey" TEXT, "decidedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "ForceCurveMapping_masterSwitchId_catalogEntryId_key" ON "ForceCurveMapping"("masterSwitchId","catalogEntryId");
CREATE INDEX "ForceCurveMapping_masterSwitchId_state_idx" ON "ForceCurveMapping"("masterSwitchId","state");
CREATE UNIQUE INDEX "ForceCurveMapping_noMatchKey_key" ON "ForceCurveMapping"("noMatchKey");
CREATE TABLE "ForceCurveReviewCase" ("id" TEXT PRIMARY KEY, "masterSwitchId" TEXT, "catalogEntryId" TEXT, "kind" TEXT NOT NULL, "status" "ForceCurveReviewStatus" NOT NULL DEFAULT 'OPEN', "reason" TEXT NOT NULL, "payload" JSONB, "resolution" "ForceCurveMappingState", "resolvedById" TEXT, "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "ForceCurveReviewCase_status_kind_idx" ON "ForceCurveReviewCase"("status","kind");
CREATE TABLE "ForceCurveSyncRun" ("id" TEXT PRIMARY KEY, "source" TEXT NOT NULL, "revision" TEXT NOT NULL, "status" "ForceCurveSyncStatus" NOT NULL DEFAULT 'RUNNING', "cursor" TEXT, "beforeCount" INTEGER NOT NULL DEFAULT 0, "afterCount" INTEGER NOT NULL DEFAULT 0, "newCount" INTEGER NOT NULL DEFAULT 0, "changedCount" INTEGER NOT NULL DEFAULT 0, "staleCount" INTEGER NOT NULL DEFAULT 0, "unmatchedCount" INTEGER NOT NULL DEFAULT 0, "reviewCount" INTEGER NOT NULL DEFAULT 0, "errorCount" INTEGER NOT NULL DEFAULT 0, "errors" JSONB, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "completedAt" TIMESTAMP(3), "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE UNIQUE INDEX "ForceCurveSyncRun_source_revision_key" ON "ForceCurveSyncRun"("source","revision");
ALTER TABLE "ForceCurveFeedback" ADD COLUMN "masterSwitchId" TEXT, ADD COLUMN "catalogEntryId" TEXT, ADD COLUMN "reviewCaseId" TEXT;
ALTER TABLE "ForceCurveMapping" ADD CONSTRAINT "ForceCurveMapping_masterSwitchId_fkey" FOREIGN KEY ("masterSwitchId") REFERENCES "MasterSwitch"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ForceCurveMapping" ADD CONSTRAINT "ForceCurveMapping_catalogEntryId_fkey" FOREIGN KEY ("catalogEntryId") REFERENCES "ForceCurveCatalogEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveMapping" ADD CONSTRAINT "ForceCurveMapping_decidedById_fkey" FOREIGN KEY ("decidedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveReviewCase" ADD CONSTRAINT "ForceCurveReviewCase_masterSwitchId_fkey" FOREIGN KEY ("masterSwitchId") REFERENCES "MasterSwitch"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveReviewCase" ADD CONSTRAINT "ForceCurveReviewCase_catalogEntryId_fkey" FOREIGN KEY ("catalogEntryId") REFERENCES "ForceCurveCatalogEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveReviewCase" ADD CONSTRAINT "ForceCurveReviewCase_resolvedById_fkey" FOREIGN KEY ("resolvedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveFeedback" ADD CONSTRAINT "ForceCurveFeedback_masterSwitchId_fkey" FOREIGN KEY ("masterSwitchId") REFERENCES "MasterSwitch"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveFeedback" ADD CONSTRAINT "ForceCurveFeedback_catalogEntryId_fkey" FOREIGN KEY ("catalogEntryId") REFERENCES "ForceCurveCatalogEntry"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ForceCurveFeedback" ADD CONSTRAINT "ForceCurveFeedback_reviewCaseId_fkey" FOREIGN KEY ("reviewCaseId") REFERENCES "ForceCurveReviewCase"("id") ON DELETE SET NULL ON UPDATE CASCADE;
